from PIL import Image
import numpy as np, cv2
a=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(np.float32)
g=cv2.cvtColor(a.astype(np.uint8),cv2.COLOR_RGB2GRAY)
for name,roi in [('center',(105,45,145,90)),('right',(175,45,200,70)),('all',(0,0,256,144))]:
 x0,y0,x1,y1=roi
 z=g[y0:y1,x0:x1]
 zu=cv2.resize(z,None,fx=4,fy=4,interpolation=cv2.INTER_CUBIC)
 zu=cv2.GaussianBlur(zu,(7,7),1.5)
 cs=cv2.HoughCircles(zu,cv2.HOUGH_GRADIENT,dp=1,minDist=20,param1=80,param2=25,minRadius=8,maxRadius=40)
 print(name)
 if cs is not None:
  for x,y,r in cs[0][:20]: print(round(x/4+x0,2),round(y/4+y0,2),round(r/4,2))
for cx,cy in [(120.5,72),(188,56),(165,88),(120,72)]:
 print('center',cx,cy)
 for r in range(0,16):
  vals=[]
  for ang in np.linspace(0,2*np.pi,16,endpoint=False):
   x=int(round(cx+r*np.cos(ang)));y=int(round(cy+r*np.sin(ang)))
   if 0<=x<256 and 0<=y<144: vals.append(a[y,x])
  print(r,np.mean(vals,0).round(1) if vals else None)
